/* Ingreso — alta de uno o varios equipos nuevos bajo una misma recepción.
   Reutiliza la API existente: POST /api/dispositivo (crea el equipo) y
   POST /api/movimientos (deja registrado el ingreso en el historial). */

const TIPO_IMG = {
  D3: "data:image/png;base64,",
  "D3+": "data:image/png;base64,",
  EBD: "data:image/png;base64,",
};

function imagenParaTipo(nombreTipo) {
  if (!nombreTipo) return null;
  const key = Object.keys(TIPO_IMG).find(k => nombreTipo.toUpperCase().includes(k));
  return key ? TIPO_IMG[key] : null;
}

let TIPOS_EQUIPO = [];

async function cargarCatalogos() {
  const cat = await apiFetch("catalogos.php");
  TIPOS_EQUIPO = cat.tipos_equipo || [];

  const selDeposito = document.getElementById("ing-deposito");
  selDeposito.innerHTML = '<option value="">Seleccionar…</option>' +
    (cat.deposito || []).map(u => `<option value="${u.id}">${u.nombre}</option>`).join("");

  const selLote = document.getElementById("ing-lote");
  selLote.innerHTML = '<option value="">—</option>' +
    (cat.lotes || []).map(l => `<option value="${l.id}">${l.nombre}</option>`).join("");
}

function opcionesTipoEquipo() {
  return '<option value="">Seleccionar…</option>' +
    TIPOS_EQUIPO.map(t => `<option value="${t.id}" data-nombre="${t.nombre}">${t.nombre}</option>`).join("");
}

function agregarFilaEquipo() {
  const tpl = document.getElementById("tpl-equipo-row");
  const nodo = tpl.content.firstElementChild.cloneNode(true);

  const selTipo = nodo.querySelector("[data-tipo]");
  selTipo.innerHTML = opcionesTipoEquipo();

  const preview = nodo.querySelector("[data-preview]");
  const actualizarPreview = () => {
    const opt = selTipo.selectedOptions[0];
    const nombre = opt ? opt.dataset.nombre : null;
    const img = imagenParaTipo(nombre);
    preview.innerHTML = img ? `<img src="${img}" alt="">` : "";
  };
  selTipo.addEventListener("change", actualizarPreview);

  nodo.querySelector("[data-quitar]").addEventListener("click", () => {
    const filas = document.querySelectorAll("#lista-equipos [data-row]");
    if (filas.length <= 1) {
      // nunca dejar la lista vacía: en vez de quitar, limpia la fila
      nodo.querySelectorAll("input").forEach(i => (i.value = ""));
      selTipo.value = "";
      actualizarPreview();
      return;
    }
    nodo.remove();
  });

  document.getElementById("lista-equipos").appendChild(nodo);
}

document.getElementById("btn-agregar-equipo").addEventListener("click", agregarFilaEquipo);

function normalizarMacCliente(mac) {
  const limpio = (mac || "").replace(/[^0-9A-Fa-f]/g, "").toUpperCase();
  if (limpio.length !== 12) return limpio || null;
  return limpio.match(/.{2}/g).join(":");
}

async function cargarHistorialIngresos() {
  const filas = await apiFetch("movimientos.php", { params: { tipo_movimiento: "ingreso", limite: 20 } });
  document.getElementById("tabla-ingresos").innerHTML = filas.map(m => `
    <tr>
      <td>${formatearFecha(m.fecha)}</td>
      <td class="mac">${m.mac_wifi || m.mac_eth || "—"}</td>
      <td>${m.tipo_movimiento}</td>
      <td>${m.destino_nombre || "—"}</td>
      <td>${m.remito || "—"}</td>
      <td>${m.ticket || "—"}</td>
      <td>${m.usuario_nombre || "—"}</td>
    </tr>
  `).join("") || `<tr><td colspan="7" class="text-center text-muted py-3">Todavía no se registraron ingresos</td></tr>`;
}

document.getElementById("btn-registrar-ingreso").addEventListener("click", async () => {
  const filas = [...document.querySelectorAll("#lista-equipos [data-row]")];
  const depositoDestino = document.getElementById("ing-deposito").value || null;
  const loteId = document.getElementById("ing-lote").value || null;
  const fechaLlegada = document.getElementById("ing-fecha").value || null;
  const remito = document.getElementById("ing-remito").value.trim() || null;
  const factura = document.getElementById("ing-factura").value.trim() || null;
  const ticket = document.getElementById("ing-ticket").value.trim() || null;
  const motivo = document.getElementById("ing-motivo").value.trim() || null;

  const equipos = [];
  for (const fila of filas) {
    const tipoEquipoId = fila.querySelector("[data-tipo]").value;
    const macWifi = fila.querySelector("[data-mac-wifi]").value.trim();
    const macEth = fila.querySelector("[data-mac-eth]").value.trim();
    const caja = fila.querySelector("[data-caja]").value.trim() || null;
    const errorEl = fila.querySelector("[data-fila-error]");
    errorEl.classList.add("d-none");

    if (!tipoEquipoId && !macWifi && !macEth) continue; // fila vacía, se ignora

    if (!tipoEquipoId || (!macWifi && !macEth)) {
      errorEl.textContent = "Falta el tipo de equipo o al menos una MAC en esta fila.";
      errorEl.classList.remove("d-none");
      return;
    }
    equipos.push({ tipoEquipoId, macWifi: normalizarMacCliente(macWifi), macEth: normalizarMacCliente(macEth), caja, fila });
  }

  if (!equipos.length) {
    mostrarError("msg-error", "Agregá al menos un equipo con su tipo y MAC antes de registrar el ingreso.");
    return;
  }

  const resumenEl = document.getElementById("ing-resumen");
  let ok = 0, fallidos = 0;

  for (const eq of equipos) {
    try {
      const nuevo = await apiFetch("dispositivo.php", {
        method: "POST",
        body: {
          mac_wifi: eq.macWifi,
          mac_eth: eq.macEth,
          tipo_equipo_id: eq.tipoEquipoId,
          lote_id: loteId,
          caja_n: eq.caja,
          deposito_actual_id: depositoDestino,
          estado: "en_stock",
          fecha_llegada: fechaLlegada,
        },
      });

      await apiFetch("movimientos.php", {
        method: "POST",
        body: {
          dispositivo_id: nuevo.id,
          tipo_movimiento: "ingreso",
          deposito_destino_id: depositoDestino,
          remito, factura, ticket, motivo,
        },
      });
      ok++;
    } catch (err) {
      fallidos++;
      const errorEl = eq.fila.querySelector("[data-fila-error]");
      errorEl.textContent = err.message;
      errorEl.classList.remove("d-none");
    }
  }

  if (ok) {
    mostrarExito("msg-exito", `${ok} equipo(s) ingresado(s) correctamente${fallidos ? ` — ${fallidos} con error` : ""}.`);
    document.getElementById("lista-equipos").innerHTML = "";
    agregarFilaEquipo();
    document.getElementById("ing-remito").value = "";
    document.getElementById("ing-factura").value = "";
    document.getElementById("ing-ticket").value = "";
    document.getElementById("ing-motivo").value = "";
    cargarHistorialIngresos();
  } else {
    mostrarError("msg-error", "No se pudo registrar ningún equipo. Revisá los errores marcados en cada fila.");
  }
  resumenEl.textContent = "";
});

(async () => {
  const hoy = new Date().toISOString().slice(0, 10);
  document.getElementById("ing-fecha").value = hoy;
  await cargarCatalogos();
  agregarFilaEquipo();
  await cargarHistorialIngresos();
})();
